"""Small, transparent diagnostic set; not a general LLM benchmark.

References are never sent to candidate models. Code specifications and JSON
schemas are explicit, unlike the ambiguous original laboratory dataset.
"""
import hashlib
import json


def task(ident, category, prompt, reference, check=None, **extra):
    return dict(id=ident, category=category, prompt=prompt,
                reference=reference, check=check, **extra)


