def dataset_hash():
    return hashlib.sha256(json.dumps(TASKS, ensure_ascii=False, sort_keys=True).encode()).hexdigest()


def speed_task(repetitions):
    # Number of source sentences is controlled; actual input tokens come from Ollama.
    context = "В журнале лаборатории записано: датчик измеряет температуру каждые пять секунд. " * repetitions
    return task(f"speed-{repetitions}", "Скорость", context + "\nПродолжай нумерованный список наблюдений об этом журнале максимально подробно, не завершая список самостоятельно.", "")
